function scrub(root,options){const c=lifecycle(root,options),port=root.querySelector('.scrub-port'),ball=root.querySelector('.scrub-ball'),lane=root.querySelector('.scrub-lane'),bar=root.querySelector('.scrub-progress'),readout=root.querySelector('.scrub-value');let frame=0;function update(){frame=0;const max=port.scrollHeight-port.clientHeight,p=max>0?port.scrollTop/max:0;bar.style.width=p*100+'%';readout.textContent=Math.round(p*100)+'%';ball.style.transform=c.reduced?'translateX(0px)':`translateX(${p*Math.max(0,lane.clientWidth-34)}px) rotate(${p*360}deg)`}c.on(port,'scroll',()=>{if(!frame)frame=requestAnimationFrame(update)},{passive:true});c.cleanup(()=>cancelAnimationFrame(frame));c.onPause(update);update();return c}
add('adv-scroll-scrub','motion','Scroll scrub','スクロール量に連動','スクロールした量に合わせて、位置と進捗が前後に変わります。','読む進度や、移動と連動した表現。','枠の中だけをスクロールしてください。scrollイベントによる実装例です。',['スクロール','連動','scrub','進捗'],'<div class="adv-wrap"><div class="scrub-port" tabindex="0" aria-label="この枠の中を縦にスクロール"><div class="scrub-scene"><small>SCROLL INSIDE ↓ <span class="scrub-value">0%</span></small><div class="scrub-lane"><div class="scrub-ball">g</div></div><div class="scrub-track"><i class="scrub-progress"></i></div></div><div class="scrub-space">ゆっくり動かしてみよう<br>↓<br>↓<br>↑ 戻すと、動きも戻る</div></div></div>','.sample .scrub-port{width:100%;height:150px;overflow:auto;overscroll-behavior:contain;border:1px solid #bbb;border-radius:10px;scrollbar-width:thin}.sample .scrub-scene{position:sticky;top:0;padding:13px;background:#efeee7;z-index:1}.sample .scrub-scene small{display:flex;justify-content:space-between;font:9px monospace}.sample .scrub-lane{height:57px;padding-top:12px}.sample .scrub-ball{width:34px;height:34px;border-radius:50%;background:#222;color:white;display:grid;place-items:center;font-weight:700}.sample .scrub-track{height:3px;background:#d4d3cb;margin-top:8px}.sample .scrub-progress{display:block;width:0;height:100%;background:#333}.sample .scrub-space{height:360px;padding:38px 12px;line-height:4;text-align:center;font-size:11px;color:#777}',scrub,'https://developer.mozilla.org/en-US/docs/Web/API/Element/scroll_event');
function reveal(root,options){const c=lifecycle(root,options),port=root.querySelector('.reveal-port'),items=[...root.querySelectorAll('.reveal-item')],reset=root.querySelector('.reveal-reset');let observer;function arm(){observer?.disconnect();c.stop();items.forEach(n=>n.dataset.pending='true');port.scrollTop=0;if(!('IntersectionObserver'in globalThis)){items.forEach(n=>delete n.dataset.pending);return}observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(!isIntersecting||!c.live)return;delete target.dataset.pending;if(!c.reduced)c.track(target.animate([{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:500,easing:'cubic-bezier(.2,.7,.2,1)'}));observer.unobserve(target)}),{root:port,threshold:.4});items.forEach(n=>observer.observe(n))}c.on(reset,'click',arm);c.cleanup(()=>observer?.disconnect());c.onPause(()=>items.forEach(n=>delete n.dataset.pending));arm();return c}
add('adv-scroll-reveal','motion','Scroll reveal once','見えたら一度だけ再生','枠の中に入った要素が、一度だけ浮かび上がります。','読み進める順序に沿った、要素の登場。','連動型とは違い、表示位置をきっかけに時間ベースのアニメーションが始まります。',['スクロール','登場','reveal','一度'],'<div class="adv-wrap"><div class="reveal-port" tabindex="0" aria-label="スクロールするとカードが登場"><div class="reveal-intro"><b>hello,<br>scroll.</b><small>この枠の中をスクロール ↓</small></div><div class="reveal-item">01 — 見つける。</div><div class="reveal-item">02 — 名前を知る。</div><div class="reveal-item">03 — 使ってみる。</div></div><button type="button" class="reveal-reset">最初から</button></div>','.sample .reveal-port{width:100%;height:135px;overflow:auto;overscroll-behavior:contain;border:1px solid #bbb;border-radius:10px;scrollbar-width:thin;padding:12px}.sample .reveal-intro{height:145px;display:flex;flex-direction:column;gap:15px}.sample .reveal-intro b{font-size:30px;line-height:.95;letter-spacing:-.06em}.sample .reveal-item{margin:15px 0;padding:27px 12px;background:#deddd4;border-radius:7px;font-size:12px}.sample .reveal-item[data-pending]{opacity:0}',reveal,'https://developer.mozilla.org/en-US/docs/Web/API/IntersectionObserver');
function stagger(root,options){const c=lifecycle(root,options),letters=[...root.querySelectorAll('.stagger-letters i')],button=root.querySelector('.stagger-play');c.on(button,'click',()=>{c.stop();if(c.reduced)return;letters.forEach((n,i)=>c.track(n.animate([{transform:'translateY(28px) rotate(10deg)',opacity:0},{transform:'translateY(0) rotate(0)',opacity:1}],{duration:540,delay:i*100,fill:'backwards',easing:'cubic-bezier(.16,1,.3,1)'})))});return c}
