function stroke(root,options){const c=lifecycle(root,options),path=root.querySelector('.draw-path'),button=root.querySelector('.draw-toggle'),length=path.getTotalLength();let shown=true;path.style.strokeDasharray=String(length);path.style.strokeDashoffset='0';c.on(button,'click',()=>{c.stop();const from=Number(path.style.strokeDashoffset),to=shown?length:0;shown=!shown;path.style.strokeDashoffset=String(to);button.textContent=shown?'線を消す':'線を描く';if(!c.reduced)c.track(path.animate([{strokeDashoffset:from},{strokeDashoffset:to}],{duration:1300,easing:'ease-in-out'}))});return c}
