function spotlight(root,options){const c=lifecycle(root,options),zone=root.querySelector('.spot-zone');const move=e=>{const r=zone.getBoundingClientRect();zone.style.setProperty('--x',`${Math.max(0,Math.min(r.width,e.clientX-r.left))}px`);zone.style.setProperty('--y',`${Math.max(0,Math.min(r.height,e.clientY-r.top))}px`)};c.on(zone,'pointermove',move,{passive:true});c.on(zone,'pointerdown',move,{passive:true});c.on(zone,'pointerleave',()=>{zone.style.removeProperty('--x');zone.style.removeProperty('--y')});c.on(zone,'keydown',e=>{const pos={ArrowLeft:['25%','50%'],ArrowRight:['75%','50%'],ArrowUp:['50%','25%'],ArrowDown:['50%','75%']}[e.key];if(pos){e.preventDefault();zone.style.setProperty('--x',pos[0]);zone.style.setProperty('--y',pos[1])}});return c}
