function spring(root,options){const c=lifecycle(root,options),field=root.querySelector('.spring-field'),handle=root.querySelector('.spring-handle');let x=0,y=0,vx=0,vy=0,frame=0,last=0,drag=null;const paint=()=>handle.style.translate=`${x}px ${y}px`;const reset=()=>{cancelAnimationFrame(frame);frame=0;x=y=vx=vy=0;paint()};function tick(t){if(!c.live)return;const dt=Math.min(.032,(t-last)/1000||.016);last=t;vx+=(-120*x-14*vx)*dt;vy+=(-120*y-14*vy)*dt;x+=vx*dt;y+=vy*dt;paint();if(Math.abs(x)+Math.abs(y)+Math.abs(vx)+Math.abs(vy)<.3){reset();return}frame=requestAnimationFrame(tick)}function release(e){if(drag===null||e.pointerId!==drag)return;const id=drag;drag=null;try{if(handle.hasPointerCapture(id))handle.releasePointerCapture(id)}catch{}handle.classList.remove('dragging');if(c.reduced){reset();return}last=performance.now();frame=requestAnimationFrame(tick)}c.on(handle,'pointerdown',e=>{if(e.button!==0)return;cancelAnimationFrame(frame);frame=0;drag=e.pointerId;vx=vy=0;handle.setPointerCapture(e.pointerId);handle.classList.add('dragging')});c.on(handle,'pointermove',e=>{if(e.pointerId!==drag)return;const r=field.getBoundingClientRect();x=Math.max(-r.width/2+25,Math.min(r.width/2-25,e.clientX-r.left-r.width/2));y=Math.max(-r.height/2+25,Math.min(r.height/2-25,e.clientY-r.top-r.height/2));paint()});c.on(handle,'pointerup',release);c.on(handle,'pointercancel',release);c.on(handle,'lostpointercapture',e=>{if(drag===e.pointerId){drag=null;reset()}});c.on(handle,'keydown',e=>{const d={ArrowLeft:[-55,0],ArrowRight:[55,0],ArrowUp:[0,-35],ArrowDown:[0,35]}[e.key];if(!d)return;e.preventDefault();reset();[x,y]=d;paint();if(c.reduced){reset();return}last=performance.now();frame=requestAnimationFrame(tick)});c.cleanup(()=>{reset();if(drag!==null){try{handle.releasePointerCapture(drag)}catch{}}});c.onPause(reset);return c}
add('adv-spring-drag','interaction','Spring return','離すとばねで戻る','つまみを離すと、振動しながら元の位置へ戻ります。','ドラッグ操作に弾力を加える表現。','ばねの力と減衰を数値で計算しています。矢印キーでも試せます。',['ばね','spring','ドラッグ','弾力','戻る'],'<div class="adv-wrap"><div class="spring-field"><i class="spring-origin"></i><button type="button" class="spring-handle" aria-label="つかんで動かす。矢印キーでも操作できます">↔</button></div><small>つまんで、離す。 / 矢印キーでも操作</small></div>','.sample .spring-field{height:130px;width:100%;position:relative;border:1px dashed #bbb;border-radius:10px;background:radial-gradient(#bdbcb4 .7px,transparent 1px) 0 0/15px 15px}.sample .spring-origin{position:absolute;width:45px;height:45px;left:50%;top:50%;transform:translate(-50%,-50%);border:1px solid #b0aea3;border-radius:50%}.sample button.spring-handle{position:absolute;width:45px;height:45px;padding:0;left:50%;top:50%;transform:translate(-50%,-50%);border:1px solid #222;border-radius:50%;background:#222;color:white;font-size:22px;touch-action:none;user-select:none;cursor:grab}.sample button.spring-handle.dragging{cursor:grabbing}',spring,'https://developer.mozilla.org/en-US/docs/Web/API/Window/requestAnimationFrame');
function flip(root,options){const c=lifecycle(root,options),grid=root.querySelector('.flip-grid'),button=root.querySelector('.flip-order');c.on(button,'click',()=>{c.stop();const nodes=[...grid.children],before=new Map(nodes.map(n=>[n,n.getBoundingClientRect()]));grid.append(nodes[0]);if(c.reduced)return;nodes.forEach(n=>{const old=before.get(n),now=n.getBoundingClientRect(),dx=old.left-now.left,dy=old.top-now.top;c.track(n.animate([{transform:`translate(${dx}px,${dy}px)`},{transform:'translate(0,0)'}],{duration:650,easing:'cubic-bezier(.22,1,.36,1)'}))})});return c}
add('adv-flip-layout','motion','FLIP layout transition','配置換えをなめらかに','並べ替え前後の座標を測り、その差を打ち消してから動かします。','カードの並べ替えや、レイアウト変更。','FLIPはFirst・Last・Invert・Playの略です。この例は位置の変化を扱います。',['flip','配置換え','レイアウト','並べ替え'],'<div class="adv-wrap"><div class="flip-grid"><i>01</i><i>02</i><i>03</i><i>04</i></div><button type="button" class="flip-order">順番を入れ替える ↗</button></div>','.sample .flip-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;width:100%;padding:17px 0}.sample .flip-grid i{height:74px;border:1px solid #333;border-radius:7px;display:grid;place-items:center;font:600 18px monospace;font-style:normal;background:#e4e3db}.sample .flip-grid i:nth-of-type(2n){background:#333;color:#fff}',flip,'https://developer.mozilla.org/en-US/docs/Web/API/Element/getBoundingClientRect');
function orbit(root,options){const c=lifecycle(root,options),path=root.querySelector('.orbit-path'),dot=root.querySelector('.orbit-dot'),button=root.querySelector('.orbit-play'),label=root.querySelector('.adv-status');let frame=0;const length=path.getTotalLength();const place=p=>{const q=path.getPointAtLength(length*p);dot.setAttribute('cx',q.x);dot.setAttribute('cy',q.y);label.textContent=Math.round(p*100)+'%'};const stop=()=>{cancelAnimationFrame(frame);frame=0};c.on(button,'click',()=>{stop();if(c.reduced){place(1);return}const start=performance.now();const tick=t=>{if(!c.live)return;const p=Math.min(1,(t-start)/2200),ease=p<.5?4*p*p*p:1-Math.pow(-2*p+2,3)/2;place(ease);if(p<1)frame=requestAnimationFrame(tick);else frame=0};place(0);frame=requestAnimationFrame(tick)});c.cleanup(stop);c.onPause(()=>{stop();place(1)});place(0);return c}
